// ============================================================================
// Timezone Component
// ============================================================================
/**
 * Gets the display name for a timezone using Intl.DateTimeFormat
 * @param timezone - IANA timezone string (e.g., "America/New_York")
 * @returns User-friendly display name (e.g., "Eastern Standard Time")
 */
function getTimezoneDisplayName(timezone) {
    if (!timezone)
        return '';
    try {
        const formatter = new Intl.DateTimeFormat('en', {
            timeZone: timezone,
            timeZoneName: 'long',
        });
        const parts = formatter.formatToParts(new Date());
        const timeZonePart = parts.find((part) => part.type === 'timeZoneName');
        return timeZonePart?.value || timezone;
    }
    catch {
        return timezone;
    }
}
/**
 * Core component that provides access to the current timezone via render props.
 *
 * @component
 * @example
 * ```tsx
 * <Timezone>
 *   {({ timezone, displayName }) => (
 *     <span>{displayName}</span>  // "Eastern Standard Time"
 *   )}
 * </Timezone>
 * ```
 */
export function Timezone(props) {
    const bookingService = useService(BookingServiceDefinition);
    const timezone = bookingService.timezone.get();
    const displayName = getTimezoneDisplayName(timezone);
    return props.children({ timezone, displayName });
}
/**
 * Core component that provides access to time slots list data via render props.
 * Use this to build list containers with GenericList.
 *
 * @component
 * @example
 * ```tsx
 * <ListData>
 *   {({ timeSlots, hasMore, isLoading, loadMore, hasSelectedTimeSlot }) => (
 *     <GenericList.Root items={timeSlots} hasMore={hasMore} isLoading={isLoading} loadMore={loadMore}>
 *       {children}
 *     </GenericList.Root>
 *   )}
 * </ListData>
 * ```
 */
export function ListData(props) {
    const service = useService(TimeSlotListServiceDefinition);
    const bookingService = useService(BookingServiceDefinition);
    const selectedTimeSlot = bookingService.serviceSelections.get()[0]?.timeSlot;
    return props.children({
        timeSlots: service.timeSlots.get(),
        hasMore: service.hasMore.get(),
        isLoading: service.isLoading.get(),
        error: service.error.get(),
        loadMore: service.actions.loadMore,
        hasSelectedTimeSlot: !!selectedTimeSlot,
    });
}
/**
 * Core component that provides access to date range data and actions via render props.
 * Use this to build date range inputs for calendar/week view navigation.
 *
 * @component
 * @example
 * ```tsx
 * <DateRange>
 *   {({ startDate, endDate, setDateRange }) => (
 *     <MyDateRangePicker
 *       start={startDate}
 *       end={endDate}
 *       onChange={(start, end) => setDateRange(start, end)}
 *     />
 *   )}
 * </DateRange>
 * ```
 */
export function DateRange(props) {
    const service = useService(TimeSlotListServiceDefinition);
    const bookingService = useService(BookingServiceDefinition);
    const dateRange = service.dateRange.get();
    const timezone = bookingService.timezone.get();
    return props.children({
        startDate: dateRange.start,
        endDate: dateRange.end,
        setDateRange: service.actions.setDateRange,
        timezone,
    });
}
